//! Generated by tools/gen_art.py; do not edit. ASSETS.md describes the format.
//! art.bin holds every frame's pixel stream: palette indices, 0 = transparent,
//! RLE (byte = (n << 4) | index, n < 15: run n + 1, n == 15: run 16 + next
//! byte, runs continue across rows) or raw (4 bits per pixel, row-major, low
//! nibble first). Palettes are cart-api DisplayColor bits (r low, b high).

pub const Pic = enum(u8) {
    title_bg, // 160x128, 1 frame(s): Title background: sunset prairie, mountains, trail ruts
    title_wagon, // 90x36, 2 frame(s): Title sprite: the wagon and two oxen, wheels and legs in 2 frames
    title_logo, // 116x40, 1 frame(s): Title words THE RASPBERRY TRAIL, raspberry and cream woodtype
    strip_wagon, // 12x9, 2 frame(s): Trail strip wagon icon facing right, 2 wheel frames
    mark_start, // 7x9, 1 frame(s): Trail strip marker: Independence (a signpost)
    mark_pass, // 11x9, 1 frame(s): Trail strip marker: South Pass (a bare mountain pass)
    mark_mountains, // 11x9, 1 frame(s): Trail strip marker: Blue Mountains (snowy blue peaks)
    mark_fort, // 9x9, 1 frame(s): Trail strip marker: a fort (palisade and flag)
    mark_city, // 11x9, 1 frame(s): Trail strip marker: Oregon City (cabin under a pine)
    btn_up, // 14x14, 3 frame(s): Shooting cue button UP: frame 0 normal, 1 highlighted, 2 done
    btn_down, // 14x14, 3 frame(s): Shooting cue button DOWN: frame 0 normal, 1 highlighted, 2 done
    btn_left, // 14x14, 3 frame(s): Shooting cue button LEFT: frame 0 normal, 1 highlighted, 2 done
    btn_right, // 14x14, 3 frame(s): Shooting cue button RIGHT: frame 0 normal, 1 highlighted, 2 done
    btn_a, // 14x14, 3 frame(s): Shooting cue button A: frame 0 normal, 1 highlighted, 2 done
    btn_b, // 14x14, 3 frame(s): Shooting cue button B: frame 0 normal, 1 highlighted, 2 done
    v_wagon_breaks, // 64x40, 1 frame(s): Vignette: wagon breakdown, the front wheel off and broken
    v_ox_injured, // 64x40, 1 frame(s): Vignette: an injured ox lying down, a bandaged leg
    v_ox_wanders, // 64x40, 1 frame(s): Vignette: an ox wanders off; an empty yoke and a question mark
    v_daughter_arm, // 64x40, 1 frame(s): Vignette: a broken arm in a white sling (no gore)
    v_son_lost, // 64x40, 2 frame(s): Vignette: searching for the lost son at night, lantern and footprints
    v_bad_water, // 64x40, 1 frame(s): Vignette: a murky pond with bubbles and a warning sign
    v_heavy_rain, // 64x40, 2 frame(s): Vignette: heavy rain over the wagon, 2 frames
    v_hail, // 64x40, 2 frame(s): Vignette: hail stones bouncing around the wagon, 2 frames
    v_fire, // 64x40, 2 frame(s): Vignette: fire in the wagon, flames and smoke, 2 frames
    v_fog, // 64x40, 1 frame(s): Vignette: the wagon fading into fog
    v_snake, // 64x40, 1 frame(s): Vignette: a coiled rattlesnake, head up
    v_river, // 64x40, 2 frame(s): Vignette: the wagon swamped in a river crossing, 2 frames
    v_wild_animals, // 64x40, 1 frame(s): Vignette: wolves on a ridge at dusk, one howling at the moon
    v_cold, // 64x40, 1 frame(s): Vignette: bitter cold, icicles and a low thermometer
    v_blizzard, // 64x40, 2 frame(s): Vignette: a blizzard burying the wagon, 2 frames
    v_mountains, // 64x40, 1 frame(s): Vignette: rugged mountains and a switchback trail
    v_fort, // 64x40, 1 frame(s): Vignette: a frontier fort, palisade, blockhouse and flag
    v_riders, // 64x40, 1 frame(s): Vignette: riders ahead, horse-and-rider silhouettes at sunset
    v_bandits, // 64x40, 1 frame(s): Vignette: masked bandits in the moonlight
    v_illness, // 64x40, 1 frame(s): Vignette: illness, a medicine bottle and spoon
    v_helpful_food, // 64x40, 1 frame(s): Vignette: a basket of wild raspberries and berries (no people)
    v_hunt_result, // 64x40, 1 frame(s): Vignette: the hunt's result, a haunch of meat and the rifle
    v_south_pass, // 64x40, 1 frame(s): Vignette: South Pass, a wide grassy saddle with no snow
    v_doctor, // 64x40, 1 frame(s): Vignette: the doctor's bag and a bandage roll
    shoot_hunt, // 160x80, 1 frame(s): Shooting scene: hunting, a buffalo and a deer on the prairie
    shoot_riders, // 160x80, 1 frame(s): Shooting scene: riders charging out of the sunset
    shoot_bandits, // 160x80, 1 frame(s): Shooting scene: bandits behind the rocks at night
    shoot_animals, // 160x80, 1 frame(s): Shooting scene: wild animals, wolves at dusk
    muzzle_flash, // 18x18, 2 frame(s): Shot sprite: muzzle flash, 2 frames
    mark_hit, // 18x18, 1 frame(s): Shot result: a hit, raspberry starburst
    mark_miss, // 18x14, 1 frame(s): Shot result: a miss, a puff of dust
    tombstone, // 160x96, 1 frame(s): Death: a tombstone on the prairie at dusk; the UI writes the cause on it
    arrival, // 160x96, 1 frame(s): Arrival: Oregon City, cabins by the river under Mt Hood
};

